package com.friendinneed.consent; import static org.junit.jupiter.api.Assertions.*; import org.junit.jupiter.api.Test;
class TokenEncryptionServiceTest { @Test void roundTrip(){TokenEncryptionService service=new TokenEncryptionService("01234567890123456789012345678901");assertEquals("secret",service.decrypt(service.encrypt("secret")));}@Test void wrongKeyFails(){String token=new TokenEncryptionService("01234567890123456789012345678901").encrypt("secret");assertThrows(IllegalArgumentException.class,()->new TokenEncryptionService("abcdefghijabcdefghijabcdefghijab").decrypt(token));} }
